"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["59942"],{23282(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio","status":422,"titulo":"A lista de campos p\xfablicos n\xe3o pode ser vazia"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio","requisitos":[],"oQueAconteceu":["A divulga\xe7\xe3o p\xfablica diz quais campos de quem prestou o certame aparecem nas listas p\xfablicas de\\nresultado. Enquanto o processo n\xe3o tem configura\xe7\xe3o expl\xedcita, ele divulga s\xf3 o n\xfamero de\\ninscri\xe7\xe3o, que \xe9 o padr\xe3o minimizado. A defini\xe7\xe3o trouxe `camposPublicos` como uma lista vazia, e\\numa lista vazia n\xe3o \xe9 nem uma amplia\xe7\xe3o nem a volta ao padr\xe3o: o sistema a recusa.","A recusa acontece depois de o sistema encontrar o processo e aceitar a precondi\xe7\xe3o de edi\xe7\xe3o.\\nComo as demais confer\xeancias da lista s\xf3 valem quando ela tem itens, esta causa n\xe3o vem junto de\\n[`campo_nao_permitido`](/erros/uniplus.selecao.configuracao_divulgacao.campo_nao_permitido) nem de\\n[`numero_inscricao_obrigatorio`](/erros/uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio).\\nEla pode vir junto de\\n[`justificativa_muito_longa`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_muito_longa)\\nou de\\n[`justificativa_caractere_invalido`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_caractere_invalido),\\nque s\xe3o conferidas sobre o texto enviado e n\xe3o dependem da lista; nesse caso, as viola\xe7\xf5es saem\\njuntas no array `errors[]`.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz essa combina\xe7\xe3o, porque a\\ndefini\xe7\xe3o a recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica, sem a lista\\n`errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["- **Voltar ao padr\xe3o (s\xf3 o n\xfamero de inscri\xe7\xe3o):** envie `camposPublicos` nulo, o que remove a\\n  configura\xe7\xe3o expl\xedcita do processo.\\n- **Ampliar a divulga\xe7\xe3o:** envie a lista com `NUMERO_INSCRICAO` e, se for o caso, com\\n  `NOME_ABREVIADO` ou com `NOME`, este \xfaltimo acompanhado de justificativa.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a divulga\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);